#!/usr/bin/env bash
# muselink-common.sh - shared configuration and SSH helpers for every VM-side
# MuseLink script. Source it, never execute it:
#     . "$(dirname "$0")/lib/muselink-common.sh" || exit 2
#
# Site values (PC address, user, tool dir, key paths ...) live in ONE config
# file, by default ~/.config/muselink/muselink.env; MUSELINK_CONFIG overrides.
# Generated by vm/install.sh from the site file (template
# config/muselink.site.example.json). Nothing site-specific is in code.

# The real home comes from passwd, not $HOME: exec shells on the Muse VM have
# been seen with HOME drifting to /root, and ssh then read the wrong
# known_hosts and reported a false "Host key verification failed".
# Platform hooks run as root with HOME pointing at the agent's home, so: an
# explicit MUSELINK_HOME wins; else the passwd home if the config is there;
# else $HOME if the config is there; else the passwd home.
ML_VM_USER="$(id -un)"
_ml_pw_home="$(getent passwd "$ML_VM_USER" 2>/dev/null | cut -d: -f6)"
_ml_cfg_rel=".config/muselink/muselink.env"
if [ -n "${MUSELINK_HOME:-}" ]; then
  ML_VM_HOME="$MUSELINK_HOME"
elif [ -n "$_ml_pw_home" ] && [ -f "$_ml_pw_home/$_ml_cfg_rel" ]; then
  ML_VM_HOME="$_ml_pw_home"
elif [ -n "${HOME:-}" ] && [ -f "$HOME/$_ml_cfg_rel" ]; then
  ML_VM_HOME="$HOME"
else
  ML_VM_HOME="${_ml_pw_home:-${HOME:-/tmp}}"
fi
unset _ml_pw_home _ml_cfg_rel
export HOME="$ML_VM_HOME"

ML_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ML_VM_DIR="$(dirname "$ML_LIB_DIR")"

ML_CONFIG="${MUSELINK_CONFIG:-$ML_VM_HOME/.config/muselink/muselink.env}"
if [ ! -f "$ML_CONFIG" ]; then
  echo "muselink: config not found: $ML_CONFIG (fill muselink.site.json, then run install.sh --apply)" >&2
  return 2 2>/dev/null || exit 2
fi
# shellcheck disable=SC1090
. "$ML_CONFIG"

for _v in PC_HOST PC_USER PC_TOOL_DIR; do
  if [ -z "${!_v:-}" ]; then
    echo "muselink: $_v is not set in $ML_CONFIG" >&2
    return 2 2>/dev/null || exit 2
  fi
done
unset _v

: "${SSH_KEY:=$ML_VM_HOME/.ssh/id_ed25519}"
: "${SSH_CONFIG:=$ML_VM_HOME/.ssh/config}"
: "${KNOWN_HOSTS:=$ML_VM_HOME/.ssh/known_hosts}"
: "${HOST_KEY_CHECK:=yes}"          # accept-new only while bootstrapping
: "${USE_TUNNEL:=1}"                # 1 = reach the tailnet through the runtime CONNECT proxy
: "${TUNNEL_PORT:=3130}"
: "${MUX:=1}"                       # 1 = reuse one SSH master connection
: "${MUX_SOCK:=$ML_VM_HOME/.muselink-master.sock}"
: "${MUX_PERSIST:=1800}"
: "${PC_PYTHON:=python}"
: "${ML_STATE_DIR:=$ML_VM_HOME/hooks/state}"
: "${ML_BRIDGE_HOME:=$ML_VM_HOME/workspace/muse-bridge}"
: "${PROXY_FALLBACK:=}"             # e.g. a credential-free proxy URL for systemd/cron
: "${WAIT_POLL_SEC:=25}"            # one wait-popup call; keep under the tunnel proxy limits
export TUNNEL_PORT

# Clean environments (systemd, cron) lack the interactive shell's proxy
# variable, and ts-connect.py needs it.
if [ -z "${HTTPS_PROXY:-}${https_proxy:-}" ] && [ -n "$PROXY_FALLBACK" ]; then
  export HTTPS_PROXY="$PROXY_FALLBACK" https_proxy="$PROXY_FALLBACK"
fi

: "${PC_BRIDGE_DIR:=$PC_TOOL_DIR\\muse-bridge}"   # the mailbox (inbox/claimed/outbox/...)
ML_PC_FWD="${PC_TOOL_DIR//\\//}"    # C:/Users/x/tool (scp wants forward slashes)
ML_PC_BRIDGE_FWD="${PC_BRIDGE_DIR//\\//}"
ML_TARGET="$PC_USER@$PC_HOST"

ML_SSH_OPTS=(-i "$SSH_KEY"
  -o "UserKnownHostsFile=$KNOWN_HOSTS" -o "StrictHostKeyChecking=$HOST_KEY_CHECK"
  -o ServerAliveInterval=15 -o ServerAliveCountMax=4 -o TCPKeepAlive=yes
  -o ConnectTimeout=20)
[ -f "$SSH_CONFIG" ] && ML_SSH_OPTS=(-F "$SSH_CONFIG" "${ML_SSH_OPTS[@]}")
if [ "$USE_TUNNEL" = "1" ]; then
  ML_SSH_OPTS+=(-o "ProxyCommand=python3 $ML_VM_DIR/ts-connect.py %h %p")
fi
# ssh keeps the FIRST value it sees for an option, so tools that need their
# own ControlMaster setting (pc-master.sh) start from ML_SSH_BASE.
ML_SSH_BASE=("${ML_SSH_OPTS[@]}")
if [ "$MUX" = "1" ]; then
  ML_SSH_OPTS+=(-o ControlMaster=auto -o "ControlPath=$MUX_SOCK" -o "ControlPersist=$MUX_PERSIST")
fi

# Files created by root-run hooks must stay usable by the agent user.
ml_fix_owner() { if [ "$(id -u)" = "0" ]; then chown --reference="$ML_VM_HOME" "$@" 2>/dev/null || true; fi; }

# ------------------------------------------------------------------ basics
ml_ssh()      { ssh "${ML_SSH_OPTS[@]}" "$ML_TARGET" "$@"; }
ml_scp_to()   { scp -q "${ML_SSH_OPTS[@]}" "$1" "$ML_TARGET:$2"; }   # $2: C:/forward/slash/path
ml_scp_from() { scp -q "${ML_SSH_OPTS[@]}" "$ML_TARGET:$1" "$2"; }
ml_pc_path()  { printf '%s\\%s' "$PC_TOOL_DIR" "$1"; }                # backslash path under the tool dir
ml_pc_fwd()   { printf '%s/%s' "$ML_PC_FWD" "$1"; }

# PowerShell single-quoted literal: double every single quote.
ml_psq() { printf "'%s'" "$(printf '%s' "$1" | sed "s/'/''/g")"; }

# Request / reply ids are restricted to a charset that is inert in bash,
# cmd.exe and PowerShell alike, so they may appear inside commands.
ml_valid_id() { [[ "${1:-}" =~ ^[A-Za-z0-9][A-Za-z0-9_-]{2,95}$ ]]; }

# Run PowerShell code on the PC without any quoting layer in between: the
# script travels as -EncodedCommand (base64 of UTF-16LE). Values inside the
# script must still be PowerShell literals built with ml_psq.
ml_ps() {
  local b64
  b64="$(printf '%s' "$1" | python3 -c 'import sys,base64; print(base64.b64encode(sys.stdin.read().encode("utf-16-le")).decode())')"
  ml_ssh "powershell -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand $b64" </dev/null
}

# Run a tool-dir script with plain, pre-validated arguments.
ml_ps_file() {
  local script="$1"; shift
  ml_ssh "powershell -NoProfile -ExecutionPolicy Bypass -File \"$(ml_pc_path "$script")\" $*" </dev/null
}

# --------------------------------------------------------- inflight marker
# One line per KEY=VALUE. Readers parse it with ml_inflight_get and never
# source it, so a summary taken from popup text can never execute.
ML_INFLIGHT="$ML_STATE_DIR/popup-inflight.env"
ml_safe_text() { printf '%s' "$1" | tr -d '\r\n"`$\\;|&<>' | tr "'" ' ' | cut -c1-160; }
ml_inflight_write() {
  mkdir -p "$ML_STATE_DIR"
  local tmp="$ML_INFLIGHT.tmp.$$" kv
  : > "$tmp"
  for kv in "$@"; do printf '%s\n' "$kv" >> "$tmp"; done
  mv -f "$tmp" "$ML_INFLIGHT"
  ml_fix_owner "$ML_INFLIGHT"
}
ml_inflight_get() { [ -f "$ML_INFLIGHT" ] && grep -m1 "^$1=" "$ML_INFLIGHT" | cut -d= -f2-; }

# ------------------------------------------------------------ wait loop
# ml_wait_loop REQ_ID [BUDGET_SEC]
# Waits for the mailbox answer of REQ_ID with a series of SHORT waits
# (wait-popup.ps1 -TimeoutSeconds $WAIT_POLL_SEC), retrying transport errors
# with backoff. One long-held SSH session used to break after ~50 s through
# the Muse tunnel; short waits sidestep that, and the loop's exit is what
# wakes Muse. Prints the final wait-popup output.
# Returns 0 DONE, 3 claimed by the fallback / mismatch, 1 error, 124 budget used up.
ml_wait_loop() {
  local req="$1" budget="${2:-3600}" t0 backoff=2 out
  ml_valid_id "$req" || { echo "STATUS:ERROR bad_reqid"; return 1; }
  t0=$(date +%s)
  while :; do
    out="$(ml_ssh "powershell -NoProfile -ExecutionPolicy Bypass -File \"$(ml_pc_path wait-popup.ps1)\" -ReqId $req -TimeoutSeconds $WAIT_POLL_SEC" </dev/null 2>&1 | tr -d '\r')"
    case "$out" in
      *STATUS:DONE*) printf '%s\n' "$out"; return 0 ;;
      *STATUS:ALREADY_CLAIMED*|*STATUS:REQ_MISMATCH*) printf '%s\n' "$out"; return 3 ;;
      *STATUS:ERROR*) printf '%s\n' "$out"; return 1 ;;
      *STATUS:TIMEOUT*) backoff=2 ;;
      *) sleep "$backoff"; [ "$backoff" -lt 30 ] && backoff=$((backoff * 2)) ;;
    esac
    if [ $(( $(date +%s) - t0 )) -ge "$budget" ]; then
      echo "STATUS:WAIT_BUDGET_EXHAUSTED"
      return 124
    fi
  done
}
